const tree = $json.tree || [];
const pular = ['log.md', 'readme.md', 'claude.md', 'agents.md'];
const notas = tree.filter(t => t.type === 'blob' && t.path.toLowerCase().endsWith('.md') && !pular.includes(t.path.toLowerCase()));
return notas.map(n => ({ json: { path: n.path, sha: n.sha } }));

// Decode base64 -> UTF-8 without Buffer: the Code sandbox's Buffer shim returns
// latin1 for .toString('utf8'), which mangles accents and emoji.
function b64ToUtf8(b64) {
  const clean = String(b64 || '').replace(/\s/g, '');
  if (!clean) return '';
  return new TextDecoder('utf-8').decode(Uint8Array.from(atob(clean), (c) => c.charCodeAt(0)));
}

// Deterministic 128-bit hash in pure JS. Replaces require('crypto'), which the
// sandbox blocks unless NODE_FUNCTION_ALLOW_BUILTIN is set — a variable n8n
// cloud does not expose.
function cyrb128(str) {
  let h1 = 1779033703, h2 = 3144134277, h3 = 1013904242, h4 = 2773480762;
  for (let i = 0, k; i < str.length; i++) {
    k = str.charCodeAt(i);
    h1 = h2 ^ Math.imul(h1 ^ k, 597399067);
    h2 = h3 ^ Math.imul(h2 ^ k, 2869860233);
    h3 = h4 ^ Math.imul(h3 ^ k, 951274213);
    h4 = h1 ^ Math.imul(h4 ^ k, 2716044179);
  }
  h1 = Math.imul(h3 ^ (h1 >>> 18), 597399067);
  h2 = Math.imul(h4 ^ (h2 >>> 22), 2869860233);
  h3 = Math.imul(h1 ^ (h3 >>> 17), 951274213);
  h4 = Math.imul(h2 ^ (h4 >>> 19), 2716044179);
  return [(h1 ^ h2 ^ h3 ^ h4) >>> 0, (h2 ^ h1) >>> 0, (h3 ^ h1) >>> 0, (h4 ^ h1) >>> 0];
}
function uuidFrom(seed) {
  const hex = cyrb128(seed).map((n) => n.toString(16).padStart(8, '0')).join('');
  return `${hex.slice(0,8)}-${hex.slice(8,12)}-${hex.slice(12,16)}-${hex.slice(16,20)}-${hex.slice(20,32)}`;
}

// ── Chunking ────────────────────────────────────────────────────────────────
// One vector per note averages the whole document: ask about checkpointing and
// the vector that represents the note is a blur of "LangGraph in general".
// Splitting on '##' keeps each chunk to one idea, which is how these notes are
// already written — the structure is free, so use it instead of cutting at a
// fixed offset and landing mid-sentence.
// A note that already fits in one chunk is left whole: at ~375 tokens the
// embedding is specific enough, and splitting it would only drop the context
// that ties its sections together. Chunking is for the long reference notes.
const MAX_CHARS = 1500;
const MIN_CHARS = 200;    // below this a section is a heading with no substance

// Minimal YAML-subset reader for the frontmatter block. Enough for `key: value`
// and `key: [a, b]`, which is all these notes use — a real YAML parser is not
// available in the Code sandbox and would be overkill for a fixed shape.
function parseFrontmatter(md) {
  const m = md.match(/^---\r?\n([\s\S]*?)\r?\n---\r?\n?/);
  if (!m) return {};
  const out = {};
  for (const linha of m[1].split(/\r?\n/)) {
    const kv = linha.match(/^([A-Za-z_][\w-]*):\s*(.*)$/);
    if (!kv) continue;
    let v = kv[2].trim();
    if (v.startsWith('[') && v.endsWith(']')) {
      v = v.slice(1, -1).split(',').map((s) => s.trim().replace(/^["']|["']$/g, '')).filter(Boolean);
    } else {
      v = v.replace(/^["']|["']$/g, '');
    }
    out[kv[1]] = v;
  }
  return out;
}

function stripFrontmatter(md) {
  const m = md.match(/^---\r?\n[\s\S]*?\r?\n---\r?\n?/);
  return m ? md.slice(m[0].length) : md;
}

function splitLongSection(section) {
  if (section.length <= MAX_CHARS) return [section];
  const out = [];
  let buf = '';
  for (const para of section.split(/\n\s*\n/)) {
    if (buf && buf.length + para.length + 2 > MAX_CHARS) { out.push(buf); buf = para; }
    else { buf = buf ? `${buf}\n\n${para}` : para; }
  }
  if (buf) out.push(buf);
  return out;
}

function chunkNote(body) {
  const whole = body.trim();
  if (whole.length <= MAX_CHARS) return [whole];

  // Keep each '##' heading attached to the section it introduces.
  const sections = whole.split(/\n(?=##\s)/).map((s) => s.trim()).filter(Boolean);

  // Fold short sections into a neighbour, checking BOTH the current section and
  // the previous one. Checking both sides is what rescues a short section in
  // last position, which has no next iteration to merge it: '## Relacionado'
  // with two links embeds to noise and would outrank real content.
  const merged = [];
  for (const s of sections) {
    const last = merged.length ? merged[merged.length - 1] : null;
    const curto = s.length < MIN_CHARS || (last !== null && last.length < MIN_CHARS);
    if (last !== null && curto && last.length + s.length + 2 <= MAX_CHARS) {
      merged[merged.length - 1] = `${last}\n\n${s}`;
    } else {
      merged.push(s);
    }
  }

  const chunks = [];
  for (const section of merged) chunks.push(...splitLongSection(section));
  return chunks.length ? chunks : [whole];
}

const filtrados = $('Filtrar .md').all();
const items = $input.all();
const saida = [];

items.forEach((it, i) => {
  // Normalise line endings before anything measures length. A CRLF checkout is
  // one byte per line longer than the LF blob the API serves, which is enough to
  // push a note across the chunk boundary — chunking must not depend on how the
  // file happened to be checked out.
  const md = b64ToUtf8(it.json.content).replace(/
/g, '
');
  // Everything before the callout is the distilled note; the raw transcript
  // after it stays in the file but must not dominate the embedding.
  const texto = md.split('> [!note]')[0].trim() || md;
  const path = filtrados[i].json.path;
  const m = texto.match(/^#\s+(.+)$/m);
  const titulo = (m ? m[1] : path).replace(/[#>\[\]]/g, '').trim();

  // `tipo` separates what was written from what was merely saved, so search can
  // ask for one or the other. Empty when a note has no frontmatter.
  const meta = parseFrontmatter(texto);
  const tipo = typeof meta.tipo === 'string' ? meta.tipo : '';

  const pedacos = chunkNote(stripFrontmatter(texto));

  pedacos.forEach((pedaco, idx) => {
    const cab = pedaco.match(/^##\s+(.+)$/m);
    const secao = cab ? cab[1].replace(/[#>\[\]]/g, '').trim() : '';
    // Prefix the note title so a chunk read in isolation still says what it
    // belongs to — both for the embedding and for whoever reads the hit.
    const comContexto = `# ${titulo}${secao ? ` — ${secao}` : ''}\n\n${pedaco}`;
    saida.push({
      json: {
        id: uuidFrom(`${path}#${idx}`),   // stable per chunk, so re-indexing upserts
        titulo, path, secao, tipo,
        chunk_index: idx,
        chunk_total: pedacos.length,
        texto: comContexto,
      },
    });
  });
});

return saida;

const embItems = $input.all();
const meta = $('Preparar texto').all();

const points = embItems.map((it, i) => ({
  id: meta[i].json.id,
  vector: it.json.data[0].embedding,
  payload: {
    titulo: meta[i].json.titulo,
    path: meta[i].json.path,
    secao: meta[i].json.secao,
    tipo: meta[i].json.tipo,
    chunk_index: meta[i].json.chunk_index,
    chunk_total: meta[i].json.chunk_total,
    texto: meta[i].json.texto,
  },
}));

return [{ json: { points }, pairedItem: { item: 0 } }];
